      "citations": [
        {
          "event_id": "lite_evt_00044",
          "explanation": "The doctor only referenced a narrow subset of red flags and did not complete the case-specific screen or contingency instructions.",
          "quote": "没有胸闷气短、小腿突发肿痛"
        },
        {
          "event_id": "lite_evt_00101",
          "explanation": "The family still needed guidance on urgent symptoms at the end.",
          "quote": "哪些情况必须马上回医院/急诊"
        }
      ],
      "explanation": "There were no disclosed active red flags and no instruction to observe dangerous symptoms at home, but the doctor did not fully screen for sudden neurologic worsening, limb color/temperature change, severe pain, bleeding, hemoptysis, black stool, or provide a complete urgent-care plan.",
      "issue_kind": "omission",
